class Solution {
public:
    int rangeBitwiseAnd(int left, int right) {
        int i=0;
        while(left!=right)
        {
            left>>=1;
            right>>=1;
            i+=1;
        }
        return left<<i;
    }
};

class Solution:
    # @param {integer} m
    # @param {integer} n
    # @return {integer}
    def rangeBitwiseAnd(self, m, n):
        if m == 0 or n ==0:
            return 0
        b1 = bin(m)[2:]
        b2 = bin(n)[2:]

        if len(b1) != len(b2):
            s = "0"
        else:
            s = ""
            while True:
                if not b1:
                    break
                if b1[0] == b2[0]:
                    s = s + b1[0]
                else:
                    s = s + "0"*len(b1)
                    break

                b1 = b1[1:]
                b2 = b2[1:]
        return int(s, base = 2)

class Solution:
    def rangeBitwiseAnd(self, left: int, right: int) -> int:
        shift = 0
        while left < right:
            left = left >> 1
            right = right >> 1
            shift += 1
        return left << shift
